mapper.select:
SELECT INCOME_ID, TAX_YEAR, TOTAL_SALARY, WITHHELD_TAX, NATIONAL_PENSION, HEALTH_INSURANCE,
       DEPENDENTS, CHILDREN, MONTHLY_RENT, HOUSING_SAVING, PENSION_SAVING, IRP_SAVING,
       SME_REDUCTION_YN, UPDATED_AT
  FROM INCOME
 WHERE MEMBER_ID = #{memberId}
   AND TAX_YEAR = #{taxYear}
